from taf.ul.ettf.events.comparator import On, OnFailed
from taf.ul.ettf.events.event import Teardown
from taf.ul.ettf.events.lifetime_policy import OneTimeCall
from taf.ul.ettf.events.notifier import Notifier, allow_one_per_notifier_group
from taf.ul.ettf.config.globals import DEFAULT_REMOTE_HOST, IPHY0_LMP_IP
from taf.ul.ettf.utils.paths import logs_directory, unique_name
from taf.ul.ettf.logging.configs import (
    GnbSwconfigCollector,
    GnbSnapshotCollector,
    GnbTargetbdFileCollector,
    IphySnapshotCollector,
    IphySwconfigCollector,
    IphyConfigurationCollector,
    IphyTargetbdFileCollector,
    GnbScfcCollector,
    GnbRawAlarmHistoryCollector,
    GnbFiledirectoryCollector,
    IphyStartupFileCollector,
    GnbExtendedTrsCollector,
    GnbHwfFileCollector,
    SosReportCollector,
)
from taf.ul.ettf.logging.tshark_capturer import (
    UeSpecificMessagesCapturer,
    CellSpecificMessagesCapturer,
    TsharkAdminapiInfomodelMessagesCapturer,
    TsharkPduSnmpMessagesCapturer,
    TsharkSimmodeMessagesCapturer,
    TsharkThroughputMessagesCapturer,
    F1apCollector,
    L3apCollector,
)
from taf.ul.ettf.logging.syslog_collector import (
    GnbSyslogCollector,
    FirstIphySyslogCollector,
    SecondIphySyslogCollector
)
from taf.ul.ettf.logging.emil import EmilCollector


class Filenames:
    UeSpecificMessagesCapturer = "tshark_eth3_eth4"
    CellSpecificMessagesCapturer = "tshark_eth4_cell_specific"
    TsharkAdminapiInfomodelMessagesCapturer = "tshark_eth1"
    TsharkPduSnmpMessagesCapturer = "tshark_eth0"
    TsharkSimmodeMessagesCapturer = "tshark_loopback"
    TsharkThroughputMessagesCapturer = "tshark_traffic"

    def get(self, class_name):
        return getattr(self, class_name)


class Logging():
    @staticmethod
    def _start(collector, trigger_condition=On):
        Notifier().register(collector.stop, trigger_condition(Teardown), OneTimeCall())
        collector.start()

    def with_capturing_ue_specific_messages(self):
        self._start(UeSpecificMessagesCapturer(logs_directory(), unique_name(Filenames.UeSpecificMessagesCapturer)))

    def with_capturing_cell_specific_messages(self):
        self._start(CellSpecificMessagesCapturer(logs_directory(), unique_name(Filenames.CellSpecificMessagesCapturer)))

    def with_capturing_adminapi_infomodel_messages(self):
        self._start(TsharkAdminapiInfomodelMessagesCapturer(logs_directory(), unique_name(Filenames.TsharkAdminapiInfomodelMessagesCapturer)))

    def with_capturing_pdu_snmp_messages(self):
        self._start(TsharkPduSnmpMessagesCapturer(logs_directory(), unique_name(Filenames.TsharkPduSnmpMessagesCapturer)))

    def with_capturing_simmode_internal_messages(self):
        self._start(TsharkSimmodeMessagesCapturer(logs_directory(), unique_name(Filenames.TsharkSimmodeMessagesCapturer)))

    def with_traffic_messages_from_wts(self):
        self._start(TsharkThroughputMessagesCapturer(logs_directory(), unique_name(Filenames.TsharkThroughputMessagesCapturer)))

    def with_capturing_f1ap_messages(self):
        self._start(F1apCollector(logs_directory()))

    def with_capturing_l3ap_messages(self):
        self._start(L3apCollector(logs_directory()))

    @allow_one_per_notifier_group
    def with_capturing_gnb_syslog(self, *remote_hosts):
        self._start(GnbSyslogCollector(logs_directory(), remote_hosts))

    @allow_one_per_notifier_group
    def with_capturing_simulators_syslog(self, *remote_hosts):
        self._start(FirstIphySyslogCollector(logs_directory(), remote_hosts))
        self._start(SecondIphySyslogCollector(logs_directory(), remote_hosts))

    def with_gnb_swconfig_collection(self, remote_host=DEFAULT_REMOTE_HOST):
        self._start(GnbSwconfigCollector(logs_directory(), remote_host))

    def with_gnb_snapshot_collection(self, remote_host=DEFAULT_REMOTE_HOST):
        self._start(GnbSnapshotCollector(logs_directory(), remote_host))

    def with_gnb_snapshot_collection_on_failure(self, remote_host=DEFAULT_REMOTE_HOST):
        self._start(GnbSnapshotCollector(logs_directory(), remote_host),
                    trigger_condition=OnFailed)

    def with_gnb_targetdb_collection(self, remote_host=DEFAULT_REMOTE_HOST):
        self._start(GnbTargetbdFileCollector(logs_directory(), remote_host))

    def with_simulator_swconfig_collection(self, remote_host=DEFAULT_REMOTE_HOST, lmp_ip=IPHY0_LMP_IP):
        self._start(IphySwconfigCollector(logs_directory(), remote_host, lmp_ip))

    def with_simulator_snapshot_collection(self, remote_host=DEFAULT_REMOTE_HOST, lmp_ip=IPHY0_LMP_IP):
        self._start(IphySnapshotCollector(logs_directory(), remote_host, lmp_ip))

    def with_simulator_snapshot_collection_on_failure(self, remote_host=DEFAULT_REMOTE_HOST, lmp_ip=IPHY0_LMP_IP):
        self._start(IphySnapshotCollector(logs_directory(), remote_host, lmp_ip),
                    trigger_condition=OnFailed)

    def with_simulator_xml_collection(self, remote_host=DEFAULT_REMOTE_HOST, lmp_ip=IPHY0_LMP_IP):
        self._start(IphyConfigurationCollector(logs_directory(), remote_host, lmp_ip))

    def with_gnb_scfc_collection(self):
        self._start(GnbScfcCollector(logs_directory()))

    def with_gnb_raw_alarm_history_collection(self, remote_host=DEFAULT_REMOTE_HOST):
        self._start(GnbRawAlarmHistoryCollector(logs_directory(), remote_host))

    def with_gnb_filedirectory_collection(self, remote_host=DEFAULT_REMOTE_HOST):
        self._start(GnbFiledirectoryCollector(logs_directory(), remote_host))

    def with_simulator_startup_file_collection(self, remote_host=DEFAULT_REMOTE_HOST, lmp_ip=IPHY0_LMP_IP):
        self._start(IphyStartupFileCollector(logs_directory(), remote_host, lmp_ip))

    def with_gnb_extended_trs_collection(self, remote_host=DEFAULT_REMOTE_HOST):
        self._start(GnbExtendedTrsCollector(logs_directory(), remote_host))

    def with_gnb_hwf_file_collection(self, remote_host=DEFAULT_REMOTE_HOST):
        self._start(GnbHwfFileCollector(logs_directory(), remote_host))

    def with_sos_report_collection(self):
        self._start(SosReportCollector(logs_directory()))

    def with_sos_report_collection_on_failure(self):
        self._start(SosReportCollector(logs_directory()), trigger_condition=OnFailed)

    def with_simulator_targetdb_collection(self, remote_host=DEFAULT_REMOTE_HOST, lmp_ip=IPHY0_LMP_IP):
        self._start(IphyTargetbdFileCollector(logs_directory(), remote_host, lmp_ip))

    def with_emil_logs_collection(self, flags=None):
        self._start(EmilCollector(logs_directory(), flags))


logging = Logging
